P='../../The Department of Historical Corrections - REV14.md'
b=open(P,encoding='utf-8').read()
def rep(a,c):
    global b
    assert b.count(a)==1,('NF/dup',b.count(a),a[:70]); b=b.replace(a,c)
def cut(start):
    global b
    assert b.count(start)==1,('cut',b.count(start),start[:60])
    i=b.index(start); j=b.index('\n\n',i)+2
    b=b[:i]+b[j:]
def after(anchor_para_start,new):
    global b
    assert b.count(anchor_para_start)==1,('after',b.count(anchor_para_start),anchor_para_start[:60])
    i=b.index(anchor_para_start); j=b.index('\n\n',i)+2
    b=b[:j]+new+'\n\n'+b[j:]

